const URL='https://fgomaujsdblpzxhnnqrg.supabase.co/rest/v1/';
const KEY='sb_publishable_JOUqLZDnfGu_yCa6k6FVDQ_AYwpr72i';
const $=id=>document.getElementById(id);
let items=[],selected=null,loadVersion=0,dialogMode='add';
const pending=new Map();let saving=false,saveTimer;
async function api(path,method='GET',body){const response=await fetch(URL+path,{method,headers:{apikey:KEY,'Content-Type':'application/json',Prefer:'return=representation,resolution=merge-duplicates'},body:body===undefined?undefined:JSON.stringify(body)});if(!response.ok){let error;try{error=await response.json()}catch{}throw new Error(error?.message||`Connection error (${response.status})`)}return response.status===204?null:response.json()}
function status(message,error=false){$('status').textContent=message;$('status').classList.toggle('error',error)}
function renderItems(){const value=selected;$('items').replaceChildren(...items.map(item=>{const option=document.createElement('option');option.value=item.id;option.textContent=item.name;return option}));$('items').value=value||'';$('edit').disabled=$('delete').disabled=!selected}
async function refresh(){try{items=await api('pm01_items?select=*&order=created_at.asc');renderItems();status('Connected · All changes saved')}catch(error){status(error.message+' · Click to retry',true)}}
function buildGrid(entries){const values=new Map(entries.map(e=>[e.entry_date,e.content]));const fragment=document.createDocumentFragment();for(let date=new Date(Date.UTC(2026,9,1));date<=new Date(Date.UTC(2027,5,30));date.setUTCDate(date.getUTCDate()+1)){const iso=date.toISOString().slice(0,10);const label=iso.slice(5)+' '+['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][date.getUTCDay()];const row=document.createElement('tr');const day=document.createElement('td');day.className='date';day.textContent=label;const cell=document.createElement('td');const input=document.createElement('textarea');input.rows=1;input.value=values.get(iso)||'';input.setAttribute('aria-label',label+' information');const itemId=selected;input.addEventListener('input',()=>queue(itemId,iso,input.value));input.addEventListener('blur',flush);cell.append(input);row.append(day,cell);fragment.append(row);if(date.getUTCDay()===0){const gap=document.createElement('tr');gap.className='spacer';gap.setAttribute('aria-hidden','true');const td=document.createElement('td');td.colSpan=2;gap.append(td);fragment.append(gap)}}$('grid').replaceChildren(fragment)}
async function choose(){selected=$('items').value||null;renderItems();const version=++loadVersion;$('grid-wrap').hidden=true;$('empty').hidden=!!selected;if(!selected)return;const item=items.find(i=>i.id===selected);$('title').textContent=item.name;$('description').textContent='October 1, 2026 – June 30, 2027 · Type in any row to add information';status('Loading…');try{const entries=await api('pm01_entries?select=*&item_id=eq.'+selected);if(version!==loadVersion)return;for(const entry of pending.values())if(entry.item_id===selected){const old=entries.find(e=>e.entry_date===entry.entry_date);if(old)old.content=entry.content;else entries.push(entry)}buildGrid(entries);$('grid-wrap').hidden=false;status(pending.size?'Unsaved changes…':'All changes saved')}catch(error){if(version===loadVersion)status(error.message+' · Click to retry',true)}}
function queue(item_id,entry_date,content){pending.set(item_id+':'+entry_date,{item_id,entry_date,content});status('Unsaved changes…');clearTimeout(saveTimer);saveTimer=setTimeout(flush,500)}
async function flush(){clearTimeout(saveTimer);if(saving||!pending.size)return;saving=true;const batch=[...pending.entries()];status('Saving…');try{await api('pm01_entries?on_conflict=item_id,entry_date','POST',batch.map(([,entry])=>entry));for(const [key,entry]of batch)if(pending.get(key)===entry)pending.delete(key);status(pending.size?'Saving…':'All changes saved')}catch(error){status('Save failed: '+error.message+' · Click to retry',true)}finally{saving=false;if(pending.size&&!$('status').classList.contains('error'))saveTimer=setTimeout(flush,100)}}
function openDialog(mode){dialogMode=mode;$('dialog-title').textContent=mode==='add'?'Add item':'Edit item';$('name').value=mode==='edit'?items.find(i=>i.id===selected).name:'';$('dialog-error').textContent='';$('dialog').showModal();$('name').focus()}
$('add').onclick=$('first-add').onclick=()=>openDialog('add');$('edit').onclick=()=>openDialog('edit');$('cancel').onclick=()=>$('dialog').close();
$('item-form').onsubmit=async event=>{event.preventDefault();const name=$('name').value.trim();if(!name){$('dialog-error').textContent='Enter an item name.';return}$('confirm').disabled=true;try{if(dialogMode==='add'){const [item]=await api('pm01_items','POST',{name});items.push(item);selected=item.id}else{await api('pm01_items?id=eq.'+selected,'PATCH',{name});items.find(i=>i.id===selected).name=name}renderItems();$('dialog').close();await choose()}catch(error){$('dialog-error').textContent=error.message}finally{$('confirm').disabled=false}};
$('delete').onclick=async()=>{const item=items.find(i=>i.id===selected);if(!item||!confirm(`Delete “${item.name}” and all its daily information?`))return;$('delete').disabled=true;try{await flush();if(pending.size||saving)throw new Error('Wait for notes to save before deleting.');await api('pm01_items?id=eq.'+item.id,'DELETE');items=items.filter(i=>i.id!==item.id);selected=null;++loadVersion;renderItems();$('grid-wrap').hidden=true;$('empty').hidden=false;$('title').textContent='Your daily plan';$('description').textContent='Choose an item on the left, or add a new item.';status('Item deleted')}catch(error){status(error.message,true)}finally{renderItems()}};
$('items').addEventListener('change',choose);
$('status').onclick=()=>{if(pending.size)flush();else if(selected)choose();else refresh()};
window.addEventListener('beforeunload',event=>{if(pending.size||saving){event.preventDefault();event.returnValue=''}});document.addEventListener('visibilitychange',()=>{if(document.hidden)flush()});window.addEventListener('online',()=>pending.size?flush():refresh());refresh();
